const DIRS = [[-1, 0], [1, 0], [0, -1], [0, 1]];

function pacificAtlantic(heights) {
  const rows = heights.length, cols = heights[0].length;
  const result = [];
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      // Pour water on (r, c) and follow it downhill, noting which oceans it reaches.
      const seen = heights.map((row) => row.map(() => false));
      let pacific = false, atlantic = false;
      const stack = [[r, c]];
      seen[r][c] = true;
      while (stack.length > 0) {
        const [cr, cc] = stack.pop();
        if (cr === 0 || cc === 0) pacific = true;                 // top or left edge
        if (cr === rows - 1 || cc === cols - 1) atlantic = true;  // bottom or right edge
        for (const [dr, dc] of DIRS) {
          const nr = cr + dr, nc = cc + dc;
          if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && !seen[nr][nc] && heights[nr][nc] <= heights[cr][cc]) {
            seen[nr][nc] = true;
            stack.push([nr, nc]);
          }
        }
      }
      if (pacific && atlantic) result.push([r, c]);
    }
  }
  return result;
}

