  for (let c = 0; c < cols; c++) climb(0, c, pacific);          // top edge
  for (let r = 0; r < rows; r++) climb(r, cols - 1, atlantic);  // right edge
  for (let c = 0; c < cols; c++) climb(rows - 1, c, atlantic);  // bottom edge
  const result = [];
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
